low = fluentqt.RadioButton('Low')
medium = fluentqt.RadioButton('Medium')
high = fluentqt.RadioButton('High')
medium.setChecked(True)
low.toggled.connect(
    lambda checked, value=low: status.setText(
    f"Selected: {value.text()}"
    ) if checked else None
)

medium.toggled.connect(
    lambda checked, value=medium: status.setText(
    f"Selected: {value.text()}"
    ) if checked else None
)

high.toggled.connect(
    lambda checked, value=high: status.setText(
    f"Selected: {value.text()}"
    ) if checked else None
)

toggle = fluentqt.ToggleButton('Bold')
toggle.toggled.connect(
    lambda checked: status.setText(
        "State: Checked" if checked else "State: Unchecked"
    )
)

list_view = fluentqt.ListView()
list_view.setSectionEnabled(True)

def section_key(row):
    if row < 3:
        return "Today"
    if row < 6:
        return "Yesterday"
    return "Earlier"

list_view.setSectionKeyFunction(section_key)
